export const SOURCES = Object.fromEntries(SITUATIONS.map(s => {
  const byId = {
    alcohol: 'drug', weed: 'drug', ecstasy: 'drug', mushrooms: 'drug',
    caffeine: 'drug', nicotine: 'drug',
    water: 'water',
    breakup: 'psych', grief: 'psych', lonely: 'psych', scroll: 'psych',
    reading: 'reading',
    phonewake: 'phonewake',
    phonenight: 'phonenight',
  };
  const kind = byId[s.id] || (/^(bike|swim)/.test(s.id) ? 'load' : 'base');
  return [s.id, SRC[kind]];
}));

